|dificultad =2
|tiempo = 20 
|ingredientes =
* 1 taza de {{ing|arroz}}
* 1 {{ing|cebolla}} 
* 1 {{ing|pimiento}}
* 4 cucharadas de {{ing|leche|leche polvo}}
* {{ing|Agua}}
* {{ing|aceite|aceite oliva}} 
* {{ing|sal}}
* {{ing||pimienta}}
* {{ing|queso|queso rallado}}
